<?php
define('RESUMEIQ_FUNCTIONS_ONLY',true);$_SERVER['REQUEST_METHOD']='GET';require_once __DIR__.'/../index.php';$pdo=db();$jobs=[];foreach($pdo->query('SELECT title,description FROM jobs') as $job)$jobs[mb_strtolower(trim($job['title']))]=$job['description'];$rows=$pdo->query("SELECT * FROM candidates WHERE source_name='NonceBlox website' AND stored_file LIKE 'nonceblox/%'")->fetchAll();$update=$pdo->prepare('UPDATE candidates SET score=?,skills_json=?,experience_json=?,analysis_json=? WHERE id=?');$processed=0;$failed=0;$ocr=0;
foreach($rows as $row){$path=__DIR__.'/../uploads/'.$row['stored_file'];$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));if(!is_file($path)){$failed++;continue;}try{$extraction=extractResumeText($path,$ext);$text=$extraction['text']??'';if(($extraction['requires_ocr']??false))$ocr++;if(trim($text)===''){$failed++;continue;}$skills=extractDetectedSkills($text);$experience=analyzeExperienceTimeline($text,$skills);$jd=$jobs[mb_strtolower(trim($row['role_title']))]??'';[$score,$matched,$missing,$tokens]=basicMatch($jd,$text);$analysis=['matched_keywords'=>$matched,'missing_keywords'=>$missing,'jd_keywords'=>$tokens,'processing_status'=>'processed','text_length'=>mb_strlen($text),'source_url'=>$row['source_url']];$update->execute([$score,json_encode($skills),json_encode($experience),json_encode($analysis),$row['id']]);$processed++;}catch(Throwable $e){$failed++;}}
echo "processed=$processed\nfailed=$failed\nocr_required=$ocr\ntotal=".count($rows)."\n";
